INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SEFER_HARAZIM','primary text','Sefer ha-Razim (The Book of the Mysteries), ed. Margalioth; trans. M. A. Morgan','Jewish Mystical'),
 ('SRC_SWORD_OF_MOSES','primary text','Harba de-Moshe (The Sword of Moses), ed. Gaster; trans. Harari','Jewish Mystical'),
 ('SRC_SEFER_RAZIEL','primary text','Sefer Raziel ha-Malakh (The Book of Raziel the Angel)','Jewish Mystical'),
 ('SRC_PICATRIX','primary text','Picatrix (Ghayat al-Hakim), trans. Greer & Warnock; ed. Pingree','Astral Magic'),
 ('SRC_LIBER_JURATUS','primary text','Liber Juratus Honorii (The Sworn Book of Honorius), ed. Hedegard','Solomonic Magic'),
 ('SRC_ARS_NOTORIA','primary text','Ars Notoria, ed./trans. Veronese','Solomonic Magic'),
 ('SRC_LIBER_RAZIELIS','primary text','Liber Razielis (Latin, compiled for Alfonso X)','Solomonic Magic')
INSERT INTO _e VALUES
 ('ENT_PGM_INVOKED_POWERS','The Invoked Powers of the Magical Papyri','Greco-Egyptian Magical','Collective','Magical pantheon','ritual invocation; binding; revelation; coercion of gods','A','Named power invoked in the Greek Magical Papyri (PGM)','Umbrella collective for the named gods, daimons and cosmic powers conjured across the Theban magical library (PGM) — a system that drew Greek, Egyptian, Jewish and Mesopotamian powers into one operative magic.'),
 ('ENT_PGM_AKEPHALOS','The Headless One (Akephalos)','Greco-Egyptian Magical','Magical deity','Headless creator-power','exorcism; creation; supreme authority; coercion of spirits','A','Named power invoked in the Greek Magical Papyri (PGM)','The Akephalos creator-god of the Stele of Jeu, invoked in PGM V for exorcism and identified with the source of cosmic order.'),
 ('ENT_PGM_KOSMOKRATOR','The Kosmokrator (Ruler of the Cosmos)','Greco-Egyptian Magical','Cosmic power','World-ruler title-power','cosmic rulership; sovereignty over the elements; supreme authority','B','Named power invoked in the Greek Magical Papyri (PGM)','Kosmokrator (''ruler of the cosmos'') is invoked as a title of the supreme magical god commanding the elements and heavenly powers.'),
 ('ENT_PGM_AERIAL_DAIMONES','The Aerial and Chthonic Daimones','Greco-Egyptian Magical','Collective','Class of intermediary spirits','intermediary spirits; aerial and underworld powers; assistance; coercion','A','Named power invoked in the Greek Magical Papyri (PGM)','The class of aerial and chthonic daimones invoked collectively in the PGM as intermediary powers and as the practitioner''s assistant-spirits (paredroi).'),
 ('ENT_PGM_ABLANATHANALBA','Ablanathanalba','Greco-Egyptian Magical','Cosmic power','Palindromic protective name','protection; apotropaic power; binding','B','Named power invoked in the Greek Magical Papyri (PGM)','Recurring protective palindrome treated as a named power, frequently paired with Sesengenbarpharanges on PGM amulets.'),
 ('ENT_PGM_SESENGENBARPHARANGES','Sesengenbarpharanges','Greco-Egyptian Magical','Cosmic power','Named protective/coercive power','protection; binding; coercion; apotropaic power','B','Named power invoked in the Greek Magical Papyri (PGM)','A recurrent named power in PGM protective and binding formulae, treated as an addressed entity (often with Ablanathanalba).'),
 ('ENT_JM_SEVEN_FIRMAMENTS','The Seven Firmaments (Raqia of Sefer ha-Razim)','Jewish Mystical','Cosmological structure','Angelic cosmology','heavenly cosmology; angelic hierarchy; ascent','A','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Sefer ha-Razim is structured as seven firmaments, the first six each cataloguing their angelic hosts and magical operations, the seventh holding the Throne of Glory and the four hayyot.'),
 ('ENT_JM_SEFER_HARAZIM_ANGELS','The Angels of the Seven Firmaments (Sefer ha-Razim)','Jewish Mystical','Collective','Angelic host','operative angelology; magic; adjuration','A','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','The vast graded host of named angels organized into encampments across the firmaments, adjured in Sefer ha-Razim''s spells for love, dreams, victory, healing and harm.'),
 ('ENT_JM_AURPNIAL','Aurpnial','Jewish Mystical','Angelic prince','Encampment chief','first firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Aurpnial heads the first of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_TIGRH','Tigrh','Jewish Mystical','Angelic prince','Encampment chief','first firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Tigrh is named as chief of one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_DNHL','Dnhl','Jewish Mystical','Angelic prince','Encampment chief','first firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Dnhl heads one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_KLMIAL','Klmial','Jewish Mystical','Angelic prince','Encampment chief','first firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Klmial commands a first-firmament encampment in Sefer ha-Razim, in whose roster Michael and Gabriel are listed.'),
 ('ENT_JM_ASIMUR','Asimur','Jewish Mystical','Angelic prince','Encampment chief','first firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Asimur is named as chief of one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_PESAKIR','Pesakir (Psbr)','Jewish Mystical','Operative angel','Encampment chief','first firmament; swift travel; messenger','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Pesakir heads the sixth encampment of the first firmament and is described with the power to cross the earth at great speed.'),
 ('ENT_JM_BOEL','Boel (Bual)','Jewish Mystical','Operative angel','Encampment chief','dreams; oneiromancy; first firmament','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Boel rules the seventh encampment of the first firmament with forty-four angels charged with the realm of dreams and revealing their meaning.'),
 ('ENT_JM_IBNIAL','Ibnial','Jewish Mystical','Angelic prince','Firmament prince','third firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Ibnial is one of the three princes governing the angelic host of the third firmament in Sefer ha-Razim.'),
 ('ENT_JM_RHTIAL','Rhtial','Jewish Mystical','Angelic prince','Firmament prince','third firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Rhtial is one of the three princes set over the angelic host of the third firmament in Sefer ha-Razim.'),
 ('ENT_JM_DLQIAL','Dlqial','Jewish Mystical','Angelic prince','Firmament prince','third firmament; angelic command','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Dlqial is one of the three third-firmament princes in Sefer ha-Razim, in whose roster the angel Nuriel is listed.'),
 ('ENT_JM_TUQPIRS','Tuqpirs','Jewish Mystical','Angelic prince','Firmament prince','sixth firmament; eastern host','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Tuqpirs heads the eastern encampments of the sixth firmament in Sefer ha-Razim.'),
 ('ENT_JM_APARKM','Aparkm','Jewish Mystical','Angelic prince','Firmament prince','sixth firmament; western host','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Aparkm heads the western encampments of the sixth firmament in Sefer ha-Razim.'),
 ('ENT_JM_MARGIOIEL','Margioiel','Jewish Mystical','Angelic prince','Sword angel','adjuration; mysteries; the Law','A','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Margioiel is one of the four angels appointed over the ''Sword'' in the Sword of Moses, set to the Law and perceiving the mysteries of above and below.'),
 ('ENT_JM_VEHADRZIOLO','Vehadrziolo (Asharuyliay)','Jewish Mystical','Angelic prince','Sword angel','adjuration; mysteries; the Law','A','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Vehadrziolo is one of the four angels appointed over the ''Sword'' in the Sword of Moses, charged with the Law and the divine mysteries.'),
 ('ENT_JM_TOTRISI','Totrisi (Totrusiyay)','Jewish Mystical','Angelic prince','Sword angel','adjuration; mysteries; the Law','A','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Totrisi is the fourth of the angels appointed over the ''Sword'' in the Sword of Moses, alongside Soqedhozi, Margioiel and Vehadrziolo.'),
 ('ENT_JM_AF_BRI','Af Bri','Jewish Mystical','Operative angel','Nature angel','rain; clouds; weather','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Af Bri, the angel of rain (name from Job 37:11), invoked in the liturgical Prayer for Rain and carried in the medieval magical-angelological tradition as overcaster of the sky.'),
 ('ENT_JM_SEFER_RAZIEL_TEACHING','The Teaching of Raziel (Sefer Raziel ha-Malakh)','Jewish Mystical','Cosmological structure','Revealed angelic knowledge','hidden knowledge; revelation; creation; astral magic','B','Named power of the late-antique/medieval Jewish magical corpus (Sefer ha-Razim, Sword of Moses, Sefer Raziel)','Sefer Raziel ha-Malakh frames its angelology, creation-midrash, names of God and astral magic as knowledge the angel Raziel taught to Adam after the Fall and to Abraham.'),
 ('ENT_AST_PLANETARY_SPIRITS','The Seven Planetary Spirits of the Picatrix','Astral Magic','Collective','Astral powers','astral magic; planetary spirits; talismanic conjuration; Sabian planetary cult','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','Picatrix Book III treats the seven planets as living spiritual powers ritually invoked (the Harranian Sabian planetary prayers), each with its Arabic name, governing spirit and prayer.'),
 ('ENT_AST_SATURN_SPIRIT','Spirit of Saturn (Zuhal)','Astral Magic','Planetary spirit','Astral powers','restriction; old age; death; agriculture; lead; melancholy; binding','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix planetary prayer to Saturn (Zuhal) addresses the planet as a cold, dark spirit of restriction, old age and death, governing lead.'),
 ('ENT_AST_JUPITER_SPIRIT','Spirit of Jupiter (al-Mushtari)','Astral Magic','Planetary spirit','Astral powers','expansion; law; justice; religion; benefice; honor; tin','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to Jupiter (al-Mushtari) invokes the planet as the benefic spirit of expansion, law, religion and honor.'),
 ('ENT_AST_MARS_SPIRIT','Spirit of Mars (al-Mirrikh)','Astral Magic','Planetary spirit','Astral powers','war; violence; iron; courage; bloodshed; conflict; surgery','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to Mars (al-Mirrikh) addresses a hot, dry, malefic spirit of war, iron and bloodshed.'),
 ('ENT_AST_SUN_SPIRIT','Spirit of the Sun (al-Shams)','Astral Magic','Planetary spirit','Astral powers','power; kingship; light; vitality; gold; honor; rulership','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to the Sun (al-Shams) invokes the solar spirit of power, kingship, light and vitality, governing gold.'),
 ('ENT_AST_VENUS_SPIRIT','Spirit of Venus (al-Zuhra)','Astral Magic','Planetary spirit','Astral powers','love; beauty; pleasure; music; fertility; copper; concord','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to Venus (al-Zuhra) addresses the benefic spirit of love, beauty, music and pleasure, governing copper.'),
 ('ENT_AST_MERCURY_SPIRIT','Spirit of Mercury (Utarid)','Astral Magic','Planetary spirit','Astral powers','intellect; writing; commerce; eloquence; learning; quicksilver; magic','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to Mercury (Utarid) invokes the mutable spirit of intellect, writing, commerce and learning, governing quicksilver.'),
 ('ENT_AST_MOON_SPIRIT','Spirit of the Moon (al-Qamar)','Astral Magic','Planetary spirit','Astral powers','flux; growth; travel; change; reflection; silver; the lunar mansions','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','The Picatrix prayer to the Moon (al-Qamar) addresses the swift spirit of flux, growth and change, governing silver and the 28 mansions.'),
 ('ENT_AST_PERFECT_NATURE','Perfect Nature (al-Tiba al-Tamm)','Astral Magic','Guardian spirit','Astral powers','celestial double; personal guardian spirit; hidden wisdom; initiation','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','In Picatrix III.6 the Perfect Nature is the sage''s personal celestial guardian-spirit, called by four names (Meegius, Betzahuech, Vacdez, Nufeneguediz), contacted through ritual to obtain hidden wisdom.'),
 ('ENT_AST_LUNAR_MANSIONS','The Twenty-Eight Lunar Mansions (Manazil al-Qamar)','Astral Magic','Collective','Astral powers','lunar astrology; magical elections; talismanic timing; binding and loosing','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','Picatrix I.4 sets out the works of the Moon through each of her 28 mansions (manazil al-qamar), used to elect favorable times for talismans and operations.'),
 ('ENT_AST_DECANS','The Thirty-Six Decans (Wujuh) of the Zodiac','Astral Magic','Decan power','Astral powers','zodiacal magic; decan images; talismanic figures; astral influences','A','Astral-magic power of the Picatrix (Ghayat al-Hakim)','Picatrix II.11 gives the magical images of the 36 decans (faces, wujuh), the three ten-degree divisions of each sign, as astral powers engraved on talismans.'),
 ('ENT_SOL_PLANETARY_ANGELS','The Seven Planetary Angels of the Grimoire Tradition','Solomonic Magic','Collective','Angelic collective','planetary governance; astral magic; the seven heavens; planetary hours','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The set of seven angels governing the planetary spheres standardized in medieval Latin astral-magic and Solomonic texts: Cassiel (Saturn), Sachiel (Jupiter), Samael (Mars), Michael (Sun), Anael (Venus), Raphael (Mercury), Gabriel (Moon).'),
 ('ENT_SOL_ARS_NOTORIA_ANGELS','The Angels of the Ars Notoria','Solomonic Magic','Collective','Angelic collective','infused knowledge; memory; eloquence; the liberal arts; theology; angelic mediation','A','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The angels invoked through the notae and orationes of the Ars Notoria so the operator might receive, through angelic mediation, instantaneous infused knowledge and perfect memory of the liberal arts, theology and Scripture.'),
 ('ENT_SOL_CASSIEL','Cassiel','Solomonic Magic','Planetary angel','Angel','Saturn; restriction; time; melancholy; the seventh sphere','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','Cassiel (Cafziel/Captiel) is named in the Latin astral-magic tradition as the angel presiding over the sphere and hours of Saturn.'),
 ('ENT_SOL_SACHIEL','Sachiel','Solomonic Magic','Planetary angel','Angel','Jupiter; prosperity; benevolence; expansion; the sixth sphere','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','Sachiel (Zachariel) is named in the Latin Solomonic corpus as the angel governing the sphere and hours of Jupiter, invoked for prosperity and favor.'),
 ('ENT_SOL_ANAEL','Anael (Angel of Venus)','Solomonic Magic','Planetary angel','Angel','Venus; love; concord; beauty; the third sphere; astral magic','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','Anael (Anachiel/Haniel) is named in the Latin astral-magic tradition as the angel of the sphere of Venus; shares its name with the Testament-of-Solomon Anael (ENT_LAT_ANAEL).'),
 ('ENT_SOL_SAMAEL_MARS','Samael (Angel of Mars)','Solomonic Magic','Planetary angel','Angel','Mars; war; severity; iron; the fifth sphere; martial hours','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','In the medieval Latin planetary-angel scheme Samael is assigned to the sphere of Mars; functionally distinct from the Gnostic/demiurgic Samael (ENT_GNO_SAMAEL) though sharing the name.'),
 ('ENT_SOL_LIBER_JURATUS_KINGS','The Angelic Kings of the Air (Liber Juratus)','Solomonic Magic','Angelic king','Angelic collective','the four directions; the winds; days of the week; planetary rule; spirits of the air','A','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The Sworn Book of Honorius names the kings of the air ruling the cardinal directions and the days/planets, each commanding subordinate aerial spirits, summoned within the operation aimed at the beatific vision.'),
 ('ENT_SOL_BEATIFIC_VISION_OP','Operation of the Beatific Vision (Liber Juratus)','Solomonic Magic','Revealed art','Ritual operation','vision of God; angelic ascent; purification; consecration; divine names','A','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The central operation of the Sworn Book is a regimen of purification, prayer and consecration culminating in the operator''s attainment of the beatific vision (the direct sight of God) mediated by angels.'),
 ('ENT_SOL_ARS_NOTORIA_NOTAE','The Notae of the Ars Notoria','Solomonic Magic','Revealed art','Ritual figures','infused knowledge; memory; the liberal arts; visual contemplation; angelic transmission','A','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The notae are the complex diagrammatic figures, inscribed with names of angels and verba ignota, contemplated while reciting the orationes; presented as a heaven-sent art by which knowledge of the sciences is infused.'),
 ('ENT_SOL_SEMIFORAS','The Semiforas / Schemhamphoras Names (Liber Razielis)','Solomonic Magic','Revealed art','Divine names','divine names; the ineffable Name; power over creation; astral and angelic operations','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','The Latin Liber Razielis transmits the Semiforas (a Latinization of Shem ha-Mephorash, the ''explicit Name''), powerful divine names revealed to Adam and the patriarchs conferring authority over creation and the angels.'),
 ('ENT_SOL_GENON','Genon and the Angelic Teachers of Eloquence (Ars Notoria)','Solomonic Magic','Angel','Angel','eloquence; the trivium; grammar, rhetoric, dialectic; infused speech','B','Angel/spirit of the early-medieval Latin Solomonic magic tradition (Ars Notoria, Liber Juratus, Liber Razielis)','Among the angels named in the orationes and notae of the Ars Notoria are figures invoked specifically for eloquence and the arts of the trivium.');
