INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_PGM_INVOKED_POWERS','PER_LATE_ANTIQUE','Umbrella collective for the named gods, daimons and cosmic powers conjured across the Theban magical library (PGM) — a system that drew Greek, Egyptian, Jewish and Mesopotamian powers into one operative magic.'),
 ('ENT_PGM_AKEPHALOS','PER_LATE_ANTIQUE','The Akephalos creator-god of the Stele of Jeu, invoked in PGM V for exorcism and identified with the source of cosmic order.'),
 ('ENT_PGM_KOSMOKRATOR','PER_LATE_ANTIQUE','Kosmokrator (''ruler of the cosmos'') is invoked as a title of the supreme magical god commanding the elements and heavenly powers.'),
 ('ENT_PGM_AERIAL_DAIMONES','PER_LATE_ANTIQUE','The class of aerial and chthonic daimones invoked collectively in the PGM as intermediary powers and as the practitioner''s assistant-spirits (paredroi).'),
 ('ENT_PGM_ABLANATHANALBA','PER_LATE_ANTIQUE','Recurring protective palindrome treated as a named power, frequently paired with Sesengenbarpharanges on PGM amulets.'),
 ('ENT_PGM_SESENGENBARPHARANGES','PER_LATE_ANTIQUE','A recurrent named power in PGM protective and binding formulae, treated as an addressed entity (often with Ablanathanalba).'),
 ('ENT_JM_SEVEN_FIRMAMENTS','PER_LATE_ANTIQUE','Sefer ha-Razim is structured as seven firmaments, the first six each cataloguing their angelic hosts and magical operations, the seventh holding the Throne of Glory and the four hayyot.'),
 ('ENT_JM_SEFER_HARAZIM_ANGELS','PER_LATE_ANTIQUE','The vast graded host of named angels organized into encampments across the firmaments, adjured in Sefer ha-Razim''s spells for love, dreams, victory, healing and harm.'),
 ('ENT_JM_AURPNIAL','PER_LATE_ANTIQUE','Aurpnial heads the first of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_TIGRH','PER_LATE_ANTIQUE','Tigrh is named as chief of one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_DNHL','PER_LATE_ANTIQUE','Dnhl heads one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_KLMIAL','PER_LATE_ANTIQUE','Klmial commands a first-firmament encampment in Sefer ha-Razim, in whose roster Michael and Gabriel are listed.'),
 ('ENT_JM_ASIMUR','PER_LATE_ANTIQUE','Asimur is named as chief of one of the seven encampments of the first firmament in Sefer ha-Razim.'),
 ('ENT_JM_PESAKIR','PER_LATE_ANTIQUE','Pesakir heads the sixth encampment of the first firmament and is described with the power to cross the earth at great speed.'),
 ('ENT_JM_BOEL','PER_LATE_ANTIQUE','Boel rules the seventh encampment of the first firmament with forty-four angels charged with the realm of dreams and revealing their meaning.'),
 ('ENT_JM_IBNIAL','PER_LATE_ANTIQUE','Ibnial is one of the three princes governing the angelic host of the third firmament in Sefer ha-Razim.'),
 ('ENT_JM_RHTIAL','PER_LATE_ANTIQUE','Rhtial is one of the three princes set over the angelic host of the third firmament in Sefer ha-Razim.'),
 ('ENT_JM_DLQIAL','PER_LATE_ANTIQUE','Dlqial is one of the three third-firmament princes in Sefer ha-Razim, in whose roster the angel Nuriel is listed.'),
 ('ENT_JM_TUQPIRS','PER_LATE_ANTIQUE','Tuqpirs heads the eastern encampments of the sixth firmament in Sefer ha-Razim.'),
 ('ENT_JM_APARKM','PER_LATE_ANTIQUE','Aparkm heads the western encampments of the sixth firmament in Sefer ha-Razim.'),
 ('ENT_JM_MARGIOIEL','PER_LATE_ANTIQUE','Margioiel is one of the four angels appointed over the ''Sword'' in the Sword of Moses, set to the Law and perceiving the mysteries of above and below.'),
 ('ENT_JM_VEHADRZIOLO','PER_LATE_ANTIQUE','Vehadrziolo is one of the four angels appointed over the ''Sword'' in the Sword of Moses, charged with the Law and the divine mysteries.'),
 ('ENT_JM_TOTRISI','PER_LATE_ANTIQUE','Totrisi is the fourth of the angels appointed over the ''Sword'' in the Sword of Moses, alongside Soqedhozi, Margioiel and Vehadrziolo.'),
 ('ENT_JM_AF_BRI','PER_JM_MEDIEVAL','Af Bri, the angel of rain (name from Job 37:11), invoked in the liturgical Prayer for Rain and carried in the medieval magical-angelological tradition as overcaster of the sky.'),
 ('ENT_JM_SEFER_RAZIEL_TEACHING','PER_JM_MEDIEVAL','Sefer Raziel ha-Malakh frames its angelology, creation-midrash, names of God and astral magic as knowledge the angel Raziel taught to Adam after the Fall and to Abraham.'),
 ('ENT_AST_PLANETARY_SPIRITS','PER_ISL_CLASSICAL','Picatrix Book III treats the seven planets as living spiritual powers ritually invoked (the Harranian Sabian planetary prayers), each with its Arabic name, governing spirit and prayer.'),
 ('ENT_AST_SATURN_SPIRIT','PER_ISL_CLASSICAL','The Picatrix planetary prayer to Saturn (Zuhal) addresses the planet as a cold, dark spirit of restriction, old age and death, governing lead.'),
 ('ENT_AST_JUPITER_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to Jupiter (al-Mushtari) invokes the planet as the benefic spirit of expansion, law, religion and honor.'),
 ('ENT_AST_MARS_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to Mars (al-Mirrikh) addresses a hot, dry, malefic spirit of war, iron and bloodshed.'),
 ('ENT_AST_SUN_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to the Sun (al-Shams) invokes the solar spirit of power, kingship, light and vitality, governing gold.'),
 ('ENT_AST_VENUS_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to Venus (al-Zuhra) addresses the benefic spirit of love, beauty, music and pleasure, governing copper.'),
 ('ENT_AST_MERCURY_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to Mercury (Utarid) invokes the mutable spirit of intellect, writing, commerce and learning, governing quicksilver.'),
 ('ENT_AST_MOON_SPIRIT','PER_ISL_CLASSICAL','The Picatrix prayer to the Moon (al-Qamar) addresses the swift spirit of flux, growth and change, governing silver and the 28 mansions.'),
 ('ENT_AST_PERFECT_NATURE','PER_ISL_CLASSICAL','In Picatrix III.6 the Perfect Nature is the sage''s personal celestial guardian-spirit, called by four names (Meegius, Betzahuech, Vacdez, Nufeneguediz), contacted through ritual to obtain hidden wisdom.'),
 ('ENT_AST_LUNAR_MANSIONS','PER_ISL_CLASSICAL','Picatrix I.4 sets out the works of the Moon through each of her 28 mansions (manazil al-qamar), used to elect favorable times for talismans and operations.'),
 ('ENT_AST_DECANS','PER_ISL_CLASSICAL','Picatrix II.11 gives the magical images of the 36 decans (faces, wujuh), the three ten-degree divisions of each sign, as astral powers engraved on talismans.'),
 ('ENT_SOL_PLANETARY_ANGELS','PER_MEDIEVAL_WEST','The set of seven angels governing the planetary spheres standardized in medieval Latin astral-magic and Solomonic texts: Cassiel (Saturn), Sachiel (Jupiter), Samael (Mars), Michael (Sun), Anael (Venus), Raphael (Mercury), Gabriel (Moon).'),
 ('ENT_SOL_ARS_NOTORIA_ANGELS','PER_MEDIEVAL_WEST','The angels invoked through the notae and orationes of the Ars Notoria so the operator might receive, through angelic mediation, instantaneous infused knowledge and perfect memory of the liberal arts, theology and Scripture.'),
 ('ENT_SOL_CASSIEL','PER_MEDIEVAL_WEST','Cassiel (Cafziel/Captiel) is named in the Latin astral-magic tradition as the angel presiding over the sphere and hours of Saturn.'),
 ('ENT_SOL_SACHIEL','PER_MEDIEVAL_WEST','Sachiel (Zachariel) is named in the Latin Solomonic corpus as the angel governing the sphere and hours of Jupiter, invoked for prosperity and favor.'),
 ('ENT_SOL_ANAEL','PER_MEDIEVAL_WEST','Anael (Anachiel/Haniel) is named in the Latin astral-magic tradition as the angel of the sphere of Venus; shares its name with the Testament-of-Solomon Anael (ENT_LAT_ANAEL).'),
 ('ENT_SOL_SAMAEL_MARS','PER_MEDIEVAL_WEST','In the medieval Latin planetary-angel scheme Samael is assigned to the sphere of Mars; functionally distinct from the Gnostic/demiurgic Samael (ENT_GNO_SAMAEL) though sharing the name.'),
 ('ENT_SOL_LIBER_JURATUS_KINGS','PER_MEDIEVAL_WEST','The Sworn Book of Honorius names the kings of the air ruling the cardinal directions and the days/planets, each commanding subordinate aerial spirits, summoned within the operation aimed at the beatific vision.'),
 ('ENT_SOL_BEATIFIC_VISION_OP','PER_MEDIEVAL_WEST','The central operation of the Sworn Book is a regimen of purification, prayer and consecration culminating in the operator''s attainment of the beatific vision (the direct sight of God) mediated by angels.'),
 ('ENT_SOL_ARS_NOTORIA_NOTAE','PER_MEDIEVAL_WEST','The notae are the complex diagrammatic figures, inscribed with names of angels and verba ignota, contemplated while reciting the orationes; presented as a heaven-sent art by which knowledge of the sciences is infused.'),
 ('ENT_SOL_SEMIFORAS','PER_MEDIEVAL_WEST','The Latin Liber Razielis transmits the Semiforas (a Latinization of Shem ha-Mephorash, the ''explicit Name''), powerful divine names revealed to Adam and the patriarchs conferring authority over creation and the angels.'),
 ('ENT_SOL_GENON','PER_MEDIEVAL_WEST','Among the angels named in the orationes and notae of the Ars Notoria are figures invoked specifically for eloquence and the arts of the trivium.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_PGM_INVOKED_POWERS','mediated_by','ENT_MAGIC','high','The collective of PGM-invoked powers is the operative pantheon of Greco-Egyptian ritual magic.',''),
